"""Verify cyclic orders generated by local swaps along tree edges."""

from heapq import heapify, heappop, heappush
from itertools import permutations, product
from math import factorial, prod


def decode_tree(size, word):
    degrees = [1] * size
    for vertex in word:
        degrees[vertex] += 1
    leaves = [vertex for vertex, degree in enumerate(degrees) if degree == 1]
    heapify(leaves)
    edges = []
    for vertex in word:
        leaf = heappop(leaves)
        edges.append((leaf, vertex))
        degrees[vertex] -= 1
        if degrees[vertex] == 1:
            heappush(leaves, vertex)
    edges.append(tuple(leaves))
    return edges


def successor(size, swap_order):
    tokens = list(range(size))
    for left, right in swap_order:
        tokens[left], tokens[right] = tokens[right], tokens[left]
    destinations = [0] * size
    for destination, token in enumerate(tokens):
        destinations[token] = destination
    return tuple(destinations)


def cycle_from(destinations, start):
    orbit = [start]
    vertex = destinations[start]
    while vertex != start:
        orbit.append(vertex)
        vertex = destinations[vertex]
    return orbit


def adjacency(size, edges):
    neighbours = [[] for _ in range(size)]
    for left, right in edges:
        neighbours[left].append(right)
        neighbours[right].append(left)
    return neighbours


def branches(neighbours, root):
    branch_of = [None] * len(neighbours)
    for first in neighbours[root]:
        pending = [(root, first)]
        while pending:
            parent, vertex = pending.pop()
            branch_of[vertex] = first
            pending.extend((vertex, nxt) for nxt in neighbours[vertex] if nxt != parent)
    return branch_of


def read_local_order(destinations, root, branch_of):
    order = []
    for vertex in cycle_from(destinations, root)[1:]:
        branch = branch_of[vertex]
        if not order or branch != order[-1]:
            order.append(branch)
    return order


def check_trees():
    trees = 0
    schedules = 0
    for size in range(2, 7):
        for word in product(range(size), repeat=size - 2):
            edges = decode_tree(size, word)
            neighbours = adjacency(size, edges)
            branch_maps = [branches(neighbours, root) for root in range(size)]
            cyclic_orders = set()
            for schedule in permutations(edges):
                destinations = successor(size, schedule)
                assert len(cycle_from(destinations, 0)) == size
                expected = adjacency(size, schedule)
                for root in range(size):
                    assert read_local_order(destinations, root, branch_maps[root]) == expected[root]
                cyclic_orders.add(destinations)
                schedules += 1
            assert len(cyclic_orders) == prod(factorial(len(incident)) for incident in neighbours)
            trees += 1
    print(f"Verified {schedules:,} schedules on {trees:,} labelled trees of orders 2–6.")
    print("Every schedule gave one cycle and every local event order was recovered.")


def check_examples():
    star = [(0, 1), (0, 2), (0, 3)]
    assert cycle_from(successor(4, star), 0) == [0, 1, 2, 3]
    assert cycle_from(successor(4, star[::-1]), 0) == [0, 3, 2, 1]
    assert len({successor(4, order) for order in permutations(star)}) == 6

    first, second, join = (0, 1), (2, 3), (1, 2)
    assert successor(4, [first, second, join]) == successor(4, [second, first, join])

    complete_triangle = [(0, 1), (1, 2), (0, 2)]
    for schedule in permutations(complete_triangle):
        result = successor(3, schedule)
        assert sorted(len(cycle_from(result, vertex)) for vertex in range(3)) == [1, 2, 2]
    print("Star, commuting disjoint swaps, and extra-edge triangle controls passed.")


if __name__ == "__main__":
    check_examples()
    check_trees()
